function renderSteps(done=0,running=-1){
  document.getElementById('wf-steps').innerHTML=STEPS.map((s,i)=>{
    let cls='',sc='ss-ready',st2='READY',ic='';
    if(i<done){cls='done';sc='ss-done';st2='✓ DONE';ic='done';}
    if(i===running){cls='running';sc='ss-running';st2='▶ RUN';ic='running';}
    return`<div class="wf-step ${cls}"><div class="wf-icon ${ic}">${s.i}</div><div class="wf-info"><div class="wf-name">${s.n}</div><div class="wf-detail">${s.d}</div></div><div class="wf-status ${sc}">${st2}</div></div>`;
  }).join('');
}

